# ======================================================================
# Exercise 1.1 — Two languages, one analysis
#   day1-01-two-languages.qmd
# ======================================================================

library(readr)
los <- read_csv("data/los_data.csv")
head(los)

library(dplyr)
los |>
  mutate(sev_band = if_else(Severity > 7, "high", "low")) |>
  group_by(sev_band) |>
  summarise(n = n(), mean_los = mean(LOS), .groups = "drop")

fit_r <- lm(LOS ~ Age + Severity, data = los)
coef(fit_r)

library(ggplot2)
ggplot(los, aes(x = Age, y = LOS)) +
  geom_point(alpha = 0.3) +
  geom_smooth(method = "lm", se = FALSE) +
  labs(x = "Age (years)", y = "Length of stay (days)")

# [solution to the `mean_high_r` task]
source("checks/checks.R")
mean_los_high <- los |> filter(Severity > 7) |> pull(LOS) |> mean()
check_metric_range(mean_los_high, 70, 100, "mean LOS, high severity")

# [solution to the `plot_fitted` task]
los$fitted <- predict(fit_r)
ggplot(los, aes(x = Age)) +
  geom_point(aes(y = LOS), alpha = 0.3) +
  geom_point(aes(y = fitted), colour = "red", size = 0.6) +
  labs(x = "Age (years)", y = "Length of stay (days)")

# ======================================================================
# Exercise 1.2 — Your first ML pipeline
#   day1-02-first-pipeline.qmd
# ======================================================================

library(readr); library(dplyr)
los <- read_csv("data/los_data.csv")
summary(los)

library(parsnip); library(rsample); library(yardstick)

set.seed(42)
split <- initial_split(los, prop = 0.8)
train <- training(split)
test  <- testing(split)

los_fit <- linear_reg() |> set_engine("lm") |> fit(LOS ~ Age + Severity, data = train)

preds <- predict(los_fit, test) |> bind_cols(test)
mae(preds, truth = LOS, estimate = .pred)

# [solution to the `baseline_r` task]
source("checks/checks.R")
mae_model    <- mae(preds, truth = LOS, estimate = .pred)$.estimate
mae_baseline <- mean(abs(test$LOS - mean(train$LOS)))
check_beats_baseline(mae_model, mae_baseline)

# [solution to the `resid_r` task]
library(ggplot2)
preds |>
  mutate(resid = LOS - .pred) |>
  ggplot(aes(x = .pred, y = resid)) +
  geom_point(alpha = 0.4) +
  geom_hline(yintercept = 0) +
  labs(x = "Predicted LOS (days)", y = "Residual (days)")

# [solution to the `bwt` task]
source("checks/checks.R")
bwt <- read_csv("data/birthweight.csv")

set.seed(42)
split_bwt <- initial_split(bwt, prop = 0.8)
train_bwt <- training(split_bwt); test_bwt <- testing(split_bwt)
check_split(train_bwt, test_bwt, bwt, prop = 0.8)

fit_bwt   <- linear_reg() |> set_engine("lm") |> fit(bw ~ bpd + ad, data = train_bwt)
preds_bwt <- predict(fit_bwt, test_bwt) |> bind_cols(test_bwt)

mae_bwt          <- mae(preds_bwt, truth = bw, estimate = .pred)$.estimate
mae_bwt_baseline <- mean(abs(test_bwt$bw - mean(train_bwt$bw)))
check_beats_baseline(mae_bwt, mae_bwt_baseline)

# ======================================================================
# Exercise 1.3 — When the patients change
#   day1-03-distribution-shift.qmd
# ======================================================================

library(readr); library(dplyr); library(ggplot2)
library(parsnip); library(rsample); library(yardstick)

los <- read_csv("data/los_data.csv")
set.seed(42)
split   <- initial_split(los, prop = 0.8)
los_fit <- linear_reg() |> set_engine("lm") |>
  fit(LOS ~ Age + Severity, data = training(split))

test_mae <- mae(bind_cols(predict(los_fit, testing(split)), testing(split)),
                truth = LOS, estimate = .pred)$.estimate
round(test_mae, 2)   # your reference number from Exercise 1.2

A <- read_csv("data/extract_A.csv")
preds_A <- predict(los_fit, new_data = A) |> bind_cols(A)
mae(preds_A, truth = LOS, estimate = .pred)

# [solution to the `mae_all_r` task]
source("checks/checks.R")
B <- read_csv("data/extract_B.csv")
C <- read_csv("data/extract_C.csv")

mae_on <- function(d) {
  mae(bind_cols(predict(los_fit, new_data = d), d), truth = LOS, estimate = .pred)$.estimate
}
res <- c(test = test_mae, A = mae_on(A), B = mae_on(B), C = mae_on(C))
check_metric_range(res[["A"]], 2, 6, "MAE on extract A")
check_metric_range(res[["C"]], 15, 30, "MAE on extract C")
round(res, 2)

# [solution to the `dists` task]
combined <- bind_rows(
  los |> mutate(source = "original"),
  A |> mutate(source = "A"), B |> mutate(source = "B"), C |> mutate(source = "C")
)

combined |> group_by(source) |>
  summarise(across(c(Age, Severity, LOS), list(mean = mean, sd = sd)), .groups = "drop")

ggplot(combined, aes(x = Age, fill = source)) +
  geom_density(alpha = 0.35) + labs(x = "Age (years)")

# [solution to the `coefs` task]
coefs <- function(d) coef(lm(LOS ~ Age + Severity, data = d))
rbind(original = coefs(los), A = coefs(A), B = coefs(B), C = coefs(C)) |> round(2)

